import asyncio, importlib, pkgutil, sys
sys.path.insert(0, "/app")
from sqlalchemy import text
import core.models  # noqa
for pkg in ("modules.crm.models", "modules.clients.models"):
    m = importlib.import_module(pkg)
    for _, name, _ in pkgutil.iter_modules(m.__path__):
        try: importlib.import_module(f"{pkg}.{name}")
        except Exception as e: print("IMPORT FAIL", pkg, name, e)
from core.models.base import Base
from core.database import async_session_factory
async def main():
    async with async_session_factory() as s:
        cols = (await s.execute(text("select table_name, column_name, udt_name from information_schema.columns where table_schema='public'"))).all()
        enums = (await s.execute(text("select t.typname, e.enumlabel from pg_enum e join pg_type t on t.oid=e.enumtypid"))).all()
    db = {}
    for t_, c, u in cols: db.setdefault(t_, {})[c] = u
    en = {}
    for t_, l in enums: en.setdefault(t_, set()).add(l)
    for tbl in sorted(Base.metadata.tables.values(), key=lambda x: x.name):
        mod = next(iter(tbl.columns)).table.metadata  # noqa
        if not any(tbl.name in str(getattr(c, 'table', '')) for c in tbl.columns): pass
        if tbl.name not in db:
            # only report tables from crm/clients modules
            print("TABLE MISSING", tbl.name); continue
        for c in tbl.columns:
            if c.name not in db[tbl.name]:
                print("COL MISSING", f"{tbl.name}.{c.name}")
            else:
                ty = c.type
                if hasattr(ty, "enums") and getattr(ty, "name", None):
                    dbn = db[tbl.name][c.name]
                    if dbn in en:
                        want = set(ty.enums); have = en[dbn]
                        if want != have:
                            print("ENUM DIFF", f"{tbl.name}.{c.name}", "model-only:", sorted(want-have), "db-only:", sorted(have-want))
                    elif dbn not in ("varchar","text"):
                        print("ENUM TYPE?", f"{tbl.name}.{c.name}", "model enum", ty.name, "db type", dbn)
asyncio.run(main())
